function UserInput({ input, onSearch, onChange, onTabChange, OnToggleChange, showFahren }) {
  return (
    <>
      <div>
        <label className="toggle-switch">
          <input onClick={() => OnToggleChange(!showFahren)} type="checkbox" />
          <span className="slider"></span>
        </label>
      </div>
      <div>
        <div className="tabs flex flex-row-reverse gap-lg">
          <div className="tab" onClick={() => onTabChange('current')}>Today</div>
          <div className="tab" onClick={() => onTabChange('future')}>14-Day Forecast</div>
        </div>
      </div>
      <div className="search-container">
        <input
          className="border-radius-xxl"
          type="text"
          value={input}
          onChange={onChange} // Use the correct prop name
          placeholder="Enter city..."
        />
        <button onClick={onSearch}>Search</button>
      </div>
    </>
  );
}

export default class App extends Component {
  constructor() {
    super();
    this.state = {
      input: '',
      activeTab: 'current', // Default to 'current'
      showFahren: true,
      results: null,
      hourlyResults: null,
      loading: false,
      error: null,
    };
  }

  componentDidMount() {
    fetchWeather = (input) => {
      this.setState({ loading: true, error: null });
      // Call your weather API here and update the state with results
      Example:
      UseWeather(input).then(data => {
        this.setState({ results: data.results, hourlyResults: data.hourlyResults, loading: false });
      }).catch(err => {
        this.setState({ error: err.message, loading: false });
      });
    };
  }

  fetchWeather = (input) => {
    this.setState({ loading: true, error: null });
    // Call your weather API here and update the state with results
    // Example:
    // UseWeather(input).then(data => {
    //   this.setState({ results: data.results, hourlyResults: data.hourlyResults, loading: false });
    // }).catch(err => {
    //   this.setState({ error: err.message, loading: false });
    // });
  };

  handleSearch = (e) => {
    e.preventDefault();
    this.fetchWeather(this.state.input); // Call fetchWeather with the input
  };

  handleFutureWeatherData = (tab) => {
    this.setState({ activeTab: tab });
  }

  handleToggleChange = (value) => {
    this.setState({ showFahren: value });
  }

  handleInputChange = (event) => {
    this.setState({ input: event.target.value });
  };




  render(){
    return (
      <div className="weather-app">
        <UserInput input={input} onChange={handleInputChange} onSearch={handleSearch} onTabChange={handleFutureWeatherData} OnToggleChange={handleToggleChange} showFahren={showFahren}/>
        <div>
          {loading && <p>LOADING ...</p>}
          {error && <p>{error}</p>} {/* Display error directly */}
          {!results && !loading && !error && <p>There are no results</p>} {/* Only show when no results and no errors */}
        </div>
        {results && (
          <div>
            {activeTab === 'current' ? <WeatherResults results={results} hourlyResults={hourlyResults}  showFahren={showFahren}/> : null}
            {activeTab === 'future' ? <WeatherForecast results={results} hourlyResults={hourlyResults} showFahren={showFahren} /> : null}
            {/* {activeTab === 'future' ? <FutureWeatherData hourlyResults={hourlyResults}/> : null} */}
          </div>

        )}
      </div>
    );
  }

}

